ct Probate review"}},{"name":"Checkbox Group with an error","description":"A set of checkboxes under one legend, from options. Explain the error in words with errorMessage and set invalid with it.","jsx":"<CheckboxGroup
  label="Send matter updates by"
  invalid
  errorMessage="Choose at least one way to send updates."
  options={[
    { value: 'email', label: 'Email' },
    { value: 'sms', label: 'SMS' },
  ]}
/>","props":{"label":"Send matter updates by","invalid":true,"errorMessage":"Choose at least one way to send updates.","options":[{"value":"email","label":"Email"},{"value":"sms","label":"SMS"}]}},{"name":"Controlled Checkbox Group","description":"The checked values as an array in your state; onValueChange gets the next array, then the change event.","jsx":"const [channels, setChannels] = useState(['email']);

<CheckboxGroup
  label="Send matter updates by"
  value={channels}
  onValueChange={setChannels}
  options={[
    { value: 'email', label: 'Email' },
    { value: 'sms', label: 'SMS' },
    { value: 'in-app', label: 'In-app' },
  ]}
/>","props":{"label":"Send matter updates by","value":"channels (state)","onValueChange":"setChannels","options":[{"value":"email","label":"Email"},{"value":"sms","label":"SMS"},{"value":"in-app","label":"In-app"}]}}],"antiExamples":[{"name":"Checking the group's checkbox for a partial selection","jsx":"<Checkbox label="All matters" checked={someSelected} />","reason":"A checked select-all reads as all of its items being checked. When only some are, set indeterminate on it so it shows a dash and is announced as mixed."},{"name":"No accessible name","jsx":"<Checkbox />","reason":"Without label, aria-label, or aria-labelledby the box still shows, but assistive technology can't say what it's for, and nothing warns you."},{"name":"Invalid with no message","jsx":"<CheckboxGroup label="Send matter updates by" invalid options={[{ value: 'email', label: 'Email' }, { value: 'sms', label: 'SMS' }]} />","reason":"The red boxes alone don't say what's wrong, and not everyone can see the color. Pair invalid with an errorMessage that explains the problem."},{"name":"One-option Checkbox Group to show an error","jsx":"<CheckboxGroup label="Conflict check" invalid errorMessage="Run a conflict check." options={[{ value: 'done', label: "I've run a conflict check" }]} />","reason":"The legend and the only option say the same thing twice. Give the single Checkbox its own errorMessage instead."},{"name":"Wrapping a single Checkbox in Field for its error","jsx":"<Field label="Conflict check" state="error" message="Run a conflict check before you open the matter.">
  <Checkbox label="I've run a conflict check" />
</Field>","reason":"Field's label replaces the checkbox's own label as its accessible name. Use the Checkbox's errorMessage for a single checkbox's error."},{"name":"Checkboxes for mutually exclusive choices","jsx":"<CheckboxGroup label="Preferred contact method" options={[{ value: 'email', label: 'Email' }, { value: 'phone', label: 'Phone' }]} />","reason":"Checkboxes let people choose any number of options. When exactly one answer applies, use Radio Group, which keeps the choice to one."}]}

