1	import * as React from 'react';
2	import type { Meta, StoryObj } from '@storybook/react-vite';
3	import { Button } from '../../../components/atoms/button';
4	import { Checkbox, CheckboxGroup } from '../../../components/atoms/checkbox';
5	import { RadioGroup } from '../../../components/atoms/radio';
6	import { Switch } from '../../../components/atoms/switch';
7	import { Field } from '../../../components/molecules/field';
8	import { InlineEdit } from '../../../components/molecules/inline-edit';
9	import { KeyValueList } from '../../../components/molecules/key-value-list';
10	import { KeyValuePair } from '../../../components/molecules/key-value-pair';
11	import { Select } from '../../../components/molecules/select';
12	import { TextArea } from '../../../components/molecules/text-area';
13	import { TextField } from '../../../components/molecules/text-field';
14	import { DatePicker } from '../../../components/organisms/date-picker';
15	import { DateTimePicker } from '../../../components/organisms/date-time-picker';
16	import { Form, FormFooter, FormRow, FormSection } from '../../../components/organisms/form';
17	import { SectionMessage } from '../../../components/organisms/section-message';
18	import { toast } from '../../../components/organisms/toast-group';
19	import styles from './forms-and-validation.module.css';
20	
21	// Examples for Patterns / Forms and Validation, built only from system components. The local
22	// stylesheet lays them out; it never restyles a component. The pattern page lists every component
23	// imported here as "Components used".
24	
25	const meta = {
26	  title: 'Patterns/Forms and Validation',
27	  parameters: { layout: 'padded' },
28	} satisfies Meta;
29	
30	export default meta;
31	type Story = StoryObj<typeof meta>;
32	
33	const TODAY = new Date(2026, 9, 19);
34	
35	const MATTER_TYPES = [
36	  { value: 'estate', label: 'Estate planning' },
37	  { value: 'probate', label: 'Probate' },
38	  { value: 'real-estate', label: 'Real estate' },
39	  { value: 'litigation', label: 'Civil litigation' },
40	  { value: 'family', label: 'Family law' },
41	];
42	
43	const ATTORNEYS = [
44	  { value: 'averill', label: 'Jordan Averill' },
45	  { value: 'okafor', label: 'Amara Okafor' },
46	  { value: 'reyes', label: 'Daniel Reyes' },
47	];
48	
49	const stop = (event: React.FormEvent) => event.preventDefault();
50	
51	/** A matter intake form: sections, rows of short fields, required fields, and helper text. */
52	export const MatterIntake: Story = {
53	  render: function Render() {
54	    const [matterType, setMatterType] = React.useState<string | null>('estate');
55	    const [attorney, setAttorney] = React.useState<string | null>('okafor');
56	    return (
57	      <Form title="New matter" description="Open a matter for a new or existing client." requiredLegend onSubmit={stop}>
58	        <FormSection title="Client">
59	          <FormRow>
60	            <Field label="First name" required>
61	              <TextField defaultValue="Jordan" autoComplete="given-name" />
62	            </Field>
63	            <Field label="Last name" required>
64	              <TextField defaultValue="Lee" autoComplete="family-name" />
65	            </Field>
66	          </FormRow>
67	          <FormRow>
68	            <Field label="Email" message="We'll send the engagement letter here.">
69	              <TextField type="email" defaultValue="jordan.lee@example.com" autoComplete="email" />
70	            </Field>
71	            <Field label="Phone">
72	              <TextField type="tel" defaultValue="(609) 555-0142" autoComplete="tel" />
73	            </Field>
74	          </FormRow>
75	          <RadioGroup
76	            label="Preferred contact"
77	            orientation="horizontal"
78	            defaultValue="email"
79	            options={[
80	              { value: 'email', label: 'Email' },
81	              { value: 'phone', label: 'Phone' },
82	              { value: 'mail', label: 'Mail' },
83	            ]}
84	          />
85	        </FormSection>
86	        <FormSection title="Matter">
87	          <FormRow>
88	            <Field label="Matter name" required message="Shown on every document in the matter.">
89	              <TextField defaultValue="Lee Living Trust" />
90	            </Field>
91	            <Field label="Matter type" required>
92	              <Select options={MATTER_TYPES} value={matterType} onChange={setMatterType} placeholder="Choose a type" />
93	            </Field>
94	          </FormRow>
95	          <FormRow>
96	            <Field label="Responsible attorney">
97	              <Select options={ATTORNEYS} value={attorney} onChange={setAttorney} placeholder="Choose an attorney" />
98	            </Field>
99	            <Field label="Opened">
100	              <DatePicker defaultValue={TODAY} today={TODAY} />
101	            </Field>
102	          </FormRow>
103	          <Field label="First meeting" message="We'll add it to the attorney's calendar.">
104	            <DateTimePicker defaultValue={new Date(2026, 9, 26, 10, 30)} today={TODAY} />
105	          </Field>
106	          <RadioGroup
107	            label="Billing"
108	            required
109	            defaultValue="flat"
110	            options={[
111	              { value: 'hourly', label: 'Hourly' },
112	              { value: 'flat', label: 'Flat fee' },
113	              { value: 'contingency', label: 'Contingency' },
114	            ]}
115	          />
116	        </FormSection>
117	        <FormSection title="Intake">
118	          <CheckboxGroup
119	            label="Documents received"
120	            description="Check everything the client has handed over."
121	            orientation="horizontal"
122	            defaultValue={['id']}
123	            options={[
124	              { value: 'id', label: 'Photo ID' },
125	              { value: 'will', label: 'Existing will' },
126	              { value: 'deeds', label: 'Property deeds' },
127	            ]}
128	          />
129	          <Field label="Intake notes" message="Only people at the firm can see these notes.">
130	            <TextArea defaultValue="Client wants the trust in place before the house closing in December." />
131	          </Field>
132	          <Checkbox label="I've run a conflict check for this client" required defaultChecked />
133	        </FormSection>
134	        <FormFooter>
135	          <Button prominence="tertiary">Cancel</Button>
136	          <Button prominence="primary" type="submit">
137	            Create matter
138	          </Button>
139	        </FormFooter>
140	      </Form>
141	    );
142	  },
143	};
144	
145	type Values = { clientName: string; matterName: string; matterType: string | null; opened: Date | null; conflictCheck: boolean };
146	
147	const EMPTY: Values = { clientName: 'Rivera', matterName: '', matterType: null, opened: null, conflictCheck: false };
148	
149	type FieldKey = keyof Values;
150	type FieldError = { key: FieldKey; label: string; message: string };
151	
152	/** Your own check, run on submit: one entry per field that needs fixing, in the order of the form. */
153	function check(values: Values): FieldError[] {
154	  const failing: Array<[boolean, FieldError]> = [
155	    [values.clientName.trim().split(/\s+/).length < 2, { key: 'clientName', label: 'Client name', message: "Enter the client's first and last name." }],
156	    [!values.matterName.trim(), { key: 'matterName', label: 'Matter name', message: 'Enter a name for the matter, such as Rivera v. Atlantic Insurance.' }],
157	    [!values.matterType, { key: 'matterType', label: 'Matter type', message: 'Choose the type of matter.' }],
158	    [!values.opened, { key: 'opened', label: 'Opened', message: 'Choose the date the matter was opened.' }],
159	    [!values.conflictCheck, { key: 'conflictCheck', label: 'Conflict check', message: 'Run a conflict check before you open the matter.' }],
160	  ];
161	  return failing.filter(([fails]) => fails).map(([, error]) => error);
162	}
163	
164	/**
165	 * Submit with the form as it is. The summary takes focus and links to each field; each field says
166	 * what to do. Fix them and submit again: the button shows it's busy, then a toast confirms.
167	 */
168	export const SubmitAndValidate: Story = {
169	  render: function Render() {
170	    const prefix = React.useId();
171	    const ids: Record<FieldKey, string> = {
172	      clientName: `${prefix}-client`,
173	      matterName: `${prefix}-matter`,
174	      matterType: `${prefix}-type`,
175	      opened: `${prefix}-opened`,
176	      conflictCheck: `${prefix}-conflict-check`,
177	    };
178	    const [values, setValues] = React.useState<Values>(EMPTY);
179	    const [submitted, setSubmitted] = React.useState(false);
180	    const [attempt, setAttempt] = React.useState(0);
181	    // What the summary lists: the errors as of the last submit. It's a live region, so it doesn't
182	    // change while people type; the fields do.
183	    const [summaryErrors, setSummaryErrors] = React.useState<FieldError[]>([]);
184	    const [saving, setSaving] = React.useState(false);
185	    const summary = React.useRef<HTMLDivElement>(null);
186	
187	    // After a failed submit, each field's error follows its value, so it clears as soon as it's fixed.
188	    const errors = submitted ? check(values) : [];
189	    const errorFor = (key: FieldKey) => errors.find((error) => error.key === key)?.message;
190	    const set = <K extends FieldKey>(key: K, value: Values[K]) => setValues((current) => ({ ...current, [key]: value }));
191	
192	    // Move focus to the summary after each failed submit, so it's read out and people start there.
193	    React.useEffect(() => {
194	      if (attempt > 0) summary.current?.focus();
195	    }, [attempt]);
196	
197	    const reset = () => {
198	      setValues(EMPTY);
199	      setSubmitted(false);
200	      setAttempt(0);
201	      setSummaryErrors([]);
202	    };
203	
204	    const submit = (event: React.FormEvent) => {
205	      event.preventDefault();
206	      if (saving) return;
207	      setSubmitted(true);
208	      const failed = check(values);
209	      setSummaryErrors(failed);
210	      if (failed.length > 0) {
211	        setAttempt((count) => count + 1);
212	        return;
213	      }
214	      setSaving(true);
215	      window.setTimeout(() => {
216	        setSaving(false);
217	        reset();
218	        toast.success('Matter created', { description: `${values.matterName} was opened for ${values.clientName}.` });
219	      }, 1500);
220	    };
221	
222	    return (
223	      <>
224	        <Form title="New matter" requiredLegend noValidate onSubmit={submit}>
225	          {summaryErrors.length > 0 ? (
226	            <FormSection>
227	              <SectionMessage
228	                ref={summary}
229	                tabIndex={-1}
230	                tone="error"
231	                title={`Fix ${summaryErrors.length === 1 ? '1 field' : `${summaryErrors.length} fields`} to create the matter`}
232	                errors={summaryErrors.map(({ key, label, message }) => ({ label, message, targetId: ids[key] }))}
233	              />
234	            </FormSection>
235	          ) : null}
236	          <FormSection title="Client">
237	            <Field label="Client name" required state={errorFor('clientName') ? 'error' : 'default'} message={errorFor('clientName') ?? 'First and last name.'}>
238	              <TextField
239	                id={ids.clientName}
240	                invalid={Boolean(errorFor('clientName'))}
241	                value={values.clientName}
242	                onChange={(event) => set('clientName', event.target.value)}
243	              />
244	            </Field>
245	          </FormSection>
246	          <FormSection title="Matter">
247	            <FormRow>
248	              <Field label="Matter name" required state={errorFor('matterName') ? 'error' : 'default'} message={errorFor('matterName')}>
249	                <TextField
250	                  id={ids.matterName}
251	                  invalid={Boolean(errorFor('matterName'))}
252	                  value={values.matterName}
253	                  onChange={(event) => set('matterName', event.target.value)}
254	                />
255	              </Field>
256	              <Field label="Matter type" required state={errorFor('matterType') ? 'error' : 'default'} message={errorFor('matterType')}>
257	                <Select
258	                  id={ids.matterType}
259	                  invalid={Boolean(errorFor('matterType'))}
260	                  options={MATTER_TYPES}
261	                  value={values.matterType}
262	                  onChange={(value) => set('matterType', value)}
263	                  placeholder="Choose a type"
264	                />
265	              </Field>
266	            </FormRow>
267	            <Field label="Opened" required state={errorFor('opened') ? 'error' : 'default'} message={errorFor('opened')}>
268	              <DatePicker id={ids.opened} invalid={Boolean(errorFor('opened'))} value={values.opened} onChange={(date) => set('opened', date)} today={TODAY} />
269	            </Field>
270	            <Checkbox
271	              id={ids.conflictCheck}
272	              label="I've run a conflict check and found no conflicts"
273	              required
274	              errorMessage={errorFor('conflictCheck')}
275	              checked={values.conflictCheck}
276	              onCheckedChange={(checked) => set('conflictCheck', checked)}
277	            />
278	          </FormSection>
279	          <FormFooter>
280	            <Button prominence="tertiary" onClick={reset}>
281	              Cancel
282	            </Button>
283	            <Button prominence="primary" type="submit" isLoading={saving}>
284	              Create matter
285	            </Button>
286	          </FormFooter>
287	        </Form>
288	      </>
289	    );
290	  },
291	};
292	
293	/** Docket numbers look like MER-P-2026-0417 here: county, court, year, number. */
294	const checkDocket = (value: string) =>
295	  /^[A-Z]{3}-[A-Z]-\d{4}-\d{4}$/.test(value.trim()) ? undefined : 'Enter it as it appears on the court notice, such as MER-P-2026-0417.';
296	
297	/**
298	 * One value changed where it's shown, and a setting that applies as soon as it's flipped: no form.
299	 * The docket number is checked with Inline Edit's `validate`: a draft in the wrong format stays in
300	 * the field with its error.
301	 */
302	export const OutsideAForm: Story = {
303	  render: function Render() {
304	    const [matterName, setMatterName] = React.useState('Lee Living Trust');
305	    const [caseNumber, setCaseNumber] = React.useState('MER-P-2026-0417');
306	    const [notify, setNotify] = React.useState(true);
307	    const [savingNotify, setSavingNotify] = React.useState(false);
308	    const flip = (next: boolean) => {
309	      setSavingNotify(true);
310	      window.setTimeout(() => {
311	        setNotify(next);
312	        setSavingNotify(false);
313	      }, 1200);
314	    };
315	    return (
316	      <div className={styles.stack}>
317	        <KeyValueList className={styles.details}>
318	          <KeyValuePair label="Matter name" underline>
319	            <InlineEdit value={matterName} onConfirm={setMatterName} actionPlacement="end" confirmLabel="Save matter name">
320	              <TextField context="inline" aria-label="Matter name" />
321	            </InlineEdit>
322	          </KeyValuePair>
323	          <KeyValuePair label="Docket number" underline>
324	            <InlineEdit value={caseNumber} onConfirm={setCaseNumber} validate={checkDocket} actionPlacement="end" confirmLabel="Save docket number">
325	              <TextField context="inline" aria-label="Docket number" />
326	            </InlineEdit>
327	          </KeyValuePair>
328	          <KeyValuePair label="Client" value="Jordan Lee" />
329	        </KeyValueList>
330	        <Switch label="Email the client when the court accepts a filing" checked={notify} isLoading={savingNotify} onCheckedChange={flip} />
331	      </div>
332	    );
333	  },
334	};
335

